// Loads the full Nigeria flaring dataset (all 6,287 records — not just the
// one anchored record) client-side from public/data.json, which is a
// size-optimized copy generated by scripts/build-public-data.js (see that
// file for why it's shaped differently from the canonical data file).

export type DatasetRecord = {
  site_name: string;
  year: number;
  flared_volume_bcm: number;
};

export type Dataset = {
  country: string;
  data_source: string;
  source_url: string;
  records: DatasetRecord[];
};

type CompactRecord = [string, number, number];

export async function loadDataset(): Promise<Dataset> {
  // Relative to the current page URL (which already includes whatever
  // basePath this is deployed under) rather than a hardcoded path — works
  // the same in local dev and once published, regardless of where.
  const url = new URL("data.json", window.location.href);
  const res = await fetch(url.toString());
  if (!res.ok) {
    throw new Error(`Failed to load dataset (HTTP ${res.status})`);
  }
  const raw = (await res.json()) as {
    country: string;
    data_source: string;
    source_url: string;
    records: CompactRecord[];
  };
  const records: DatasetRecord[] = raw.records.map(([site_name, year, flared_volume_bcm]) => ({
    site_name,
    year,
    flared_volume_bcm,
  }));
  return { country: raw.country, data_source: raw.data_source, source_url: raw.source_url, records };
}
